CREATE TABLE IF NOT EXISTS cms_ai_policies(site_id INTEGER PRIMARY KEY REFERENCES cms_sites(id) ON DELETE CASCADE,connector_key TEXT NOT NULL DEFAULT 'vazin-ai',model_key TEXT NOT NULL DEFAULT '',monthly_request_limit INTEGER NOT NULL DEFAULT 1000,allow_drafting INTEGER NOT NULL DEFAULT 1 CHECK(allow_drafting IN(0,1)),allow_translation INTEGER NOT NULL DEFAULT 1 CHECK(allow_translation IN(0,1)),allow_semantic_search INTEGER NOT NULL DEFAULT 1 CHECK(allow_semantic_search IN(0,1)),require_human_review INTEGER NOT NULL DEFAULT 1 CHECK(require_human_review IN(0,1)),settings_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_ai_prompt_templates(id INTEGER PRIMARY KEY AUTOINCREMENT,site_id INTEGER REFERENCES cms_sites(id) ON DELETE CASCADE,template_key TEXT NOT NULL,label TEXT NOT NULL,purpose TEXT NOT NULL,prompt_text TEXT NOT NULL,is_system INTEGER NOT NULL DEFAULT 0 CHECK(is_system IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(site_id,template_key));
CREATE TABLE IF NOT EXISTS cms_ai_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,page_id INTEGER REFERENCES cms_pages(id) ON DELETE SET NULL,request_key TEXT NOT NULL UNIQUE,purpose TEXT NOT NULL,model_key TEXT NOT NULL DEFAULT '',input_hash TEXT NOT NULL,output_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','completed','failed','review_required','approved','rejected')),usage_json TEXT NOT NULL DEFAULT '{}',error_message TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_cms_ai_requests_site ON cms_ai_requests(site_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS cms_ai_reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL REFERENCES cms_ai_requests(id) ON DELETE CASCADE,reviewer_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,decision TEXT NOT NULL CHECK(decision IN('approved','rejected')),note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_semantic_documents(id INTEGER PRIMARY KEY AUTOINCREMENT,site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,locale TEXT NOT NULL DEFAULT 'en',content_hash TEXT NOT NULL,embedding_json TEXT NOT NULL DEFAULT '[]',metadata_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(site_id,entity_type,entity_id,locale));
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.24.0');